using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.USR.Parientes;using GraphApi.Services.USR.Parientes;namespace GraphApi.Controllers.USR.Parientes{    /// <summary>    /// Gestión de Parientes: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("USR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Parientes")]    public class ParientesController : Controller    {        private readonly IParientesService _objService;        public ParientesController(IParientesService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Parientes, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="parienteID">ParienteID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="nombreUsuario">NombreUsuario</param>        /// <param name="correoUsuario">CorreoUsuario</param>        /// <param name="nombrePariente">NombrePariente</param>        /// <param name="parentescoID">ParentescoID</param>        /// <param name="parentesco">Parentesco</param>        /// <param name="telefonoPariente">TelefonoPariente</param>        /// <param name="correoPariente">CorreoPariente</param>        /// <param name="esContactoEmergencia">EsContactoEmergencia</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Parientes</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Parientes",            Description = "Devuelve Parientes aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadParientes>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadParientes>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? parienteID,            [FromQuery] int? usuarioID,            [FromQuery] string? nombreUsuario,            [FromQuery] string? correoUsuario,            [FromQuery] string? nombrePariente,            [FromQuery] int? parentescoID,            [FromQuery] string? parentesco,            [FromQuery] string? telefonoPariente,            [FromQuery] string? correoPariente,            [FromQuery] bool? esContactoEmergencia,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetParientesDynamic(                parienteID,                 usuarioID,                 nombreUsuario,                 correoUsuario,                 nombrePariente,                 parentescoID,                 parentesco,                 telefonoPariente,                 correoPariente,                 esContactoEmergencia,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Pariente.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Pariente a crear.</param>        /// <returns>El Pariente recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Parientes",            Description = "Inserta un nuevo Pariente en la base de datos."        )]        [ProducesResponseType(typeof(clReadParientes), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadParientes>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateParientes objInput)        {            var vCreated = await _objService.CreateParientes(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Pariente.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Pariente.</param>        /// <returns>El Pariente actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Parientes",            Description = "Actualiza uno o varios campos de Pariente existente."        )]        [ProducesResponseType(typeof(clReadParientes), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadParientes>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateParientes objInput)        {            var vUpdated = await _objService.UpdateParientes(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Pariente por su ID.        /// </summary>        [HttpDelete("{nParientesID:int}")]        [SwaggerOperation(            Summary = "Eliminar Pariente",            Description = "Borra un Pariente si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nParientesID)        {            var success = await _objService.DeleteParientes(nParientesID);            return success ? NoContent() : NotFound();        }    }}